-- Create "content_versions" table
CREATE TABLE "content_versions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "checksum" character varying NOT NULL, "imported_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "content_versions_checksum_key" ON "content_versions" ("checksum");
-- Create "users" table
CREATE TABLE "users" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "email" character varying NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
-- Create "courses" table
CREATE TABLE "courses" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "language" character varying NOT NULL, "project" character varying NOT NULL, "title" character varying NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "course_language_project" ON "courses" ("language", "project");
-- Create "exercises" table
CREATE TABLE "exercises" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "slug" character varying NOT NULL, "type" character varying NOT NULL, "title" character varying NOT NULL, "payload" jsonb NOT NULL, "content_version_exercises" bigint NULL, "course_exercises" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "exercises_content_versions_exercises" FOREIGN KEY ("content_version_exercises") REFERENCES "content_versions" ("id") ON DELETE SET NULL, CONSTRAINT "exercises_courses_exercises" FOREIGN KEY ("course_exercises") REFERENCES "courses" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "exercise_slug_course_exercises" ON "exercises" ("slug", "course_exercises");
-- Create "lessons" table
CREATE TABLE "lessons" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "slug" character varying NOT NULL, "order" bigint NOT NULL, "title" character varying NOT NULL, "minutes" bigint NOT NULL, "xp" bigint NOT NULL, "body" text NOT NULL DEFAULT '', "owned_files" jsonb NULL, "hints" jsonb NULL, "failure_explanations" jsonb NULL, "content_version_lessons" bigint NULL, "course_lessons" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "lessons_content_versions_lessons" FOREIGN KEY ("content_version_lessons") REFERENCES "content_versions" ("id") ON DELETE SET NULL, CONSTRAINT "lessons_courses_lessons" FOREIGN KEY ("course_lessons") REFERENCES "courses" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "lesson_slug_course_lessons" ON "lessons" ("slug", "course_lessons");
CREATE UNIQUE INDEX "lesson_order_course_lessons" ON "lessons" ("order", "course_lessons");
